import{careerLibraryPage as originalPage}from'./career-library-ui.js';
import{noncollege087}from'./noncollege-087-data.js';import{escapeHTML as h}from'./html.js';
export function careerLibraryPage(route,s,search=''){const base=originalPage(route,s,search);if(!['learn/training','learn/saved'].includes(route.split('?')[0]))return base;const saved=s.careerLibrary?.saved||[],q=search.trim().toLowerCase(),os=noncollege087.filter(o=>(route!=='learn/saved'||saved.includes(o.id))&&(!q||(o.title+' '+o.summary).toLowerCase().includes(q)));return base+(os.length?`<section class="guide-input-panel"><h2>More no-degree and technical routes</h2><div style="overflow:auto"><table><thead><tr><th>Career</th><th>Preparation</th><th>Annual pay proxy</th></tr></thead><tbody>${os.map(o=>`<tr><th><a href="#/journey/profession/${h(o.id)}">${h(o.title)}</a></th><td>${h(o.preparation.typicalEducation[0])}</td><td>$${Math.round(o.salary.entry).toLocaleString()}</td></tr>`).join('')}</tbody></table></div><p>Wage proxies are estimates after qualification. Requirements vary.</p></section>`:'');}
